import{_ as e,o as t,c as s,a3 as _}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-032.ZnPwdEma.jpg",p="/ReadBooks/assets/image-084.DvTrd8s9.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/12-40％的人群将沦为下流阶层？.md","filePath":"books/xialiu-shehui/12-40％的人群将沦为下流阶层？.md","lastUpdated":1794732511000}'),i={name:"books/xialiu-shehui/12-40％的人群将沦为下流阶层？.md"};function r(n,a,d,l,c,m){return t(),s("div",null,[...a[0]||(a[0]=[_('<h2 id="_40-的人群将沦为下流阶层" tabindex="-1">40%的人群将沦为下流阶层？ <a class="header-anchor" href="#_40-的人群将沦为下流阶层" aria-label="Permalink to &quot;40%的人群将沦为下流阶层？&quot;">​</a></h2><p>现今，日本的贫富分化正在拉大，有人预测今后还将更加扩大。</p><p>根据厚生劳动省的“收入再分配调查”，收入的基尼系数（测量社会财富不平等程度的指标，如财富分配平等基尼系数趋近于0，财富分配不平等则趋近于1）从1999年的0.433上升至2002年的0.498（见表1-1）。而一个国家的基尼系数达到0.5以上，即意味着国民总收入的四分之三集中在四分之一的高收入人群身上，现在的日本可以说基本上已经处于这样的状态。经过社会保障体系再分配之后的基尼系数日本为0.322，美国为0.368，英国为0.345，法国为0.288，瑞典和德国均为0.252。同以上几个经济发达国家相比，日本的贫富差距更加接近美国和英国的水平（见图1-1）。</p><p>表1-1　收入再分配的收入差距纠正效果（基尼系数）</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>（注：1999年以前的实物支付仅有医疗一项，2002年则包含医疗、护理、保育）资料出处：由厚生劳动省进行的“平成十四年度收入再分配调查”</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>图1-1　收入再分配后的收入差距之国际比较</p><p>（注：上图中日本为等价再分配收入的基尼系数，其余国家则为等价可支配收入的基尼系数）</p><p>资料出处：日本的数据引自平成十四年（2002年）收入再分配调查结果（厚生劳动省），其余国家的数据引自Luxemburg Income Study此外，从经济学上来分析，近年来贫富差距拉大的原因据说主要在于因为高龄者日益增多，而引入成果主义对30—50岁年龄段人群的影响尚未得到确认（参照大竹文雄著《日本的不平等》）。与高龄者的收入差距相比较，成果主义所导致的收入差距往往只限于大都市圈民营企业中的白领阶层，因此从整体来看其影响并不显著。</p><p>但事实是，对大都市圈民营企业的白领阶层来说，成果主义所导致的收入差距已经开始拉大了，并且毫无疑问今后还将继续扩大。</p>',11)])])}const g=e(i,[["render",r]]);export{h as __pageData,g as default};
